contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    event OwnershipTransferred(address indexed previousOwner, address indexed newOwner);

    function run(address newOwner, bool shouldSucceed) public payable {
        require(newOwner != address(0) && newOwner != address(this), "invalid newOwner");

        address initialOwner = c.owner();
        bool reverted;

        if (shouldSucceed) {
            require(msg.sender == initialOwner, "caller must be owner for success path");
            try c.transferOwnership(newOwner) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            require(msg.sender != initialOwner, "caller must not be owner for revert path");
            try c.transferOwnership(newOwner) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        address finalOwner = c.owner();

        if (msg.sender == initialOwner && !reverted) {
            assert(finalOwner == newOwner);
        } else {
            assert(reverted && finalOwner == initialOwner);
        }
    }

    receive() external payable {}
}

