contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address caller, address newOwner) public payable {
        // The test contract is the only owner from deployment; impersonate a caller by making a call from `caller` is not possible without cheatcodes,
        // so this test only exercises the owner branch because msg.sender is always this contract.
        address initialOwner = c.owner();
        bool reverted;
        try c.transferOwnership(newOwner) {
            reverted = false;
        } catch {
            reverted = true;
        }
        address finalOwner = c.owner();
        assert(initialOwner == address(this) ? (!reverted && finalOwner == newOwner) : (reverted && finalOwner == initialOwner));
    }

    receive() external payable {}
}

